(() => {
  const scroll = document.querySelector("[data-storyboard-scroll]");
  const footer = document.querySelector("[data-storyboard-plan-footer]");
  const addShot = footer.querySelector("[data-storyboard-add-shot]");
  const addAnchor = document.querySelector("[data-storyboard-add-anchor]");
  const hit = element => {
    if (!element) return false;
    const r = element.getBoundingClientRect();
    return element.contains(document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2));
  };
  return {
    width: innerWidth, height: innerHeight, lang: document.documentElement.lang,
    scrollTop: scroll.scrollTop, shots: Number(document.querySelector("[data-storyboard-row-count]").dataset.storyboardRowCount),
    toggle: Boolean(document.querySelector("[data-storyboard-anchors-toggle]")),
    anchorHit: hit(addAnchor), shotHit: hit(addShot),
    progress: footer.querySelector("[data-storyboard-progress]")?.textContent,
    backHit: hit(footer.querySelector("button")),
    generateHit: hit(footer.querySelector("[data-storyboard-batch]")),
    addLabel: addShot?.textContent
  };
})()

(() => {
  const row = document.querySelector("[data-storyboard-row=\"3\"]");
  const scroll = document.querySelector("[data-storyboard-scroll]");
  if (!row) return false;
  const box = row.getBoundingClientRect();
  const clip = scroll.getBoundingClientRect();
  return box.top >= clip.top - 1 && box.bottom <= clip.bottom + 1;
})()

